<script setup lang="ts">
import { computed, ref } from 'vue'
import type { TrendBucket } from '../types'
import { date, zone } from '../composables/investigation'
const props=defineProps<{buckets:TrendBucket[]}>(), table=ref(false), active=ref<number|null>(null)
const ceiling=computed(()=>Math.max(4,...props.buckets.map(b=>Number(b.occurrences))))
const points=computed(()=>props.buckets.map((b,i)=>({x:52+i*928/Math.max(1,props.buckets.length-1),y:180-Number(b.occurrences)/ceiling.value*150,b})))
const line=computed(()=>points.value.map((p,i)=>`${i?'L':'M'}${p.x},${p.y}`).join(' '))
</script>
<template><section class="panel trend-panel"><div class="panel-heading"><h2>Occurrence trend</h2><span class="help">{{ buckets.length }} buckets · {{ zone() }}</span></div><p class="chart-caption">Captured events, not request error rate</p><div tabindex="0" role="region" aria-label="Occurrence chart, scroll horizontally on narrow screens" class="chart-wrap"><svg preserveAspectRatio="none" viewBox="0 0 1000 220" role="img" aria-label="Captured occurrence trend"><g v-for="n in [0,1,2,3]" :key="n"><line x1="52" x2="980" :y1="180-n*50" :y2="180-n*50" stroke="#e5e7eb"/><text x="40" :y="185-n*50" text-anchor="end">{{ Math.round(ceiling*n/3) }}</text></g><path :d="line+' L980,180 L52,180 Z'" fill="#eeedff"/><path :d="line" fill="none" stroke="#4040c8" stroke-width="2"/><circle v-for="(p,i) in points" :key="p.b.at" :cx="p.x" :cy="p.y" r="4" fill="#4040c8" tabindex="0" :aria-label="date(p.b.at)+': '+p.b.occurrences+' occurrences'" @focus="active=i" @blur="active=null" @mouseenter="active=i" @mouseleave="active=null"><title>{{ date(p.b.at) }}: {{ p.b.occurrences }}</title></circle><text v-for="(p,i) in points.filter((_,i)=>i===0||i===points.length-1||i%Math.max(1,Math.floor(points.length/5))===0)" :key="i" :x="p.x" y="210" :text-anchor="i===0?'start':'end'">{{ new Date(p.b.at).toLocaleDateString('en-GB',{month:'short',day:'numeric',hour:'2-digit',timeZone:zone()}) }}</text></svg></div><div class="chart-bottom"><span class="help" role="status">{{ active!==null && points[active] ? date(points[active]!.b.at)+': '+points[active]!.b.occurrences+' captured' : 'The current bucket is partial.' }}</span><button class="text-link" @click="table=!table">{{ table?'Hide':'View' }} chart data</button></div><div v-if="table" class="table-scroll"><table><caption class="sr-only">Occurrence trend data</caption><thead><tr><th>Bucket start</th><th>Occurrences</th><th>New groups</th><th>Regressions</th></tr></thead><tbody><tr v-for="b in buckets" :key="b.at"><td>{{ date(b.at) }}</td><td>{{ b.occurrences }}</td><td>{{ b.new_groups }}</td><td>{{ b.regressions }}</td></tr></tbody></table></div></section></template>
